cd /tmp/fceval-c3-t1-oyjmc0q8/work/.firecrawl/e && for f in $(ls); do echo "=== $f"; awk '
/^(API|MCP server|Developers?|Webhooks?|SDK|Integrations API)( \([0-9]+\))?$/ {blk=1; print; next}
blk && /^(### |## |Improvements|Fixes|[A-Z][A-Za-z ]+ \([0-9]+\)$)/ {blk=0}
blk && /^\[?(Product|Features)/ {blk=0}
blk {print}
' $f | cut -c1-400 | head -40; grep -n -A1 -E "^- (API|MCP|Webhooks?|OAuth|OAuth apps|OAuth Apps|SDK|API Keys|GraphQL|Developers|Agents API)\s*$" $f | grep -v "^--" | cut -c1-400; done 2>/dev/null | head -700

